#ifndef IGB_SFX_H
#define IGB_SFX_H

#include "bn_sound_item.h"
#include "bn_sound_items.h"

#include "tuning.h"

namespace igb::sfx
{

// Plays a sound effect (generated by tools/make_sounds.py) at the game's effect volume.
inline void play(const bn::sound_item& item)
{
    item.play(bn::fixed(tuning::sfx_volume_percent) / 100);
}

}

#endif
